import * as React from "react"

import { cn } from "@/lib/utils"

type ProgressProps = Omit<React.ComponentProps<"div">, "children"> & {
  value: number
  max?: number
  /** What is being done, in words ("Uploading 12 files"). It also names the bar. */
  label?: string
}

/** A hairline that fills, and the percentage set as an italic numeral. Native <progress> underneath. */
function Progress({ value, max = 100, label, className, ...props }: ProgressProps) {
  const percent = max > 0 ? Math.round((Math.min(Math.max(value, 0), max) / max) * 100) : 0
  return (
    <div data-slot="progress" className={cn("db-progress", className)} {...props}>
      {label ? (
        <p data-slot="progress-label" className="db-progress-label">
          {label}
        </p>
      ) : null}
      <p data-slot="progress-value" className="db-progress-value" aria-hidden="true">
        <span>{percent}</span>
        <small>%</small>
      </p>
      <progress value={value} max={max} aria-label={label ?? "Progress"} />
    </div>
  )
}

export { Progress, type ProgressProps }

@layer components {
  /* ── db-progress ── a line that fills, a number that counts */
  .db-progress { display: grid; inline-size: 100%; grid-template-columns: minmax(0, 1fr) auto; align-items: baseline; row-gap: var(--db-space-3); }
  .db-progress-label { color: var(--db-graphite); }
  /* The percentage is yours: italic, in the expression face. */
  .db-progress-value { font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * var(--db-f)); font-weight: 400; line-height: 0.9; letter-spacing: 0; color: var(--db-ink); font-variant-numeric: tabular-nums; }
  .db-progress-value small { margin-inline-start: 0.08em; font-size: 0.42em; font-weight: 400; font-style: normal; font-family: var(--db-voice); letter-spacing: 0; color: var(--db-pencil); }
  .db-progress > progress {
    grid-column: 1 / -1; -webkit-appearance: none; appearance: none;
    inline-size: 100%; block-size: var(--db-stroke); border: 0; background: var(--db-rule); color: var(--db-ink);
  }
  .db-progress > progress::-webkit-progress-bar { background: var(--db-rule); }
  .db-progress > progress::-webkit-progress-value { background: var(--db-ink); transition: inline-size var(--db-moderato) var(--db-breath); }
  .db-progress > progress::-moz-progress-bar { background: var(--db-ink); }
}
